// One client record from a Stripe Checkout payment or the manual payment form.
const s = $('Onboarding Settings').first().json;
const ZERO_DECIMAL = ['BIF', 'CLP', 'DJF', 'GNF', 'JPY', 'KMF', 'KRW', 'MGA', 'PYG', 'RWF', 'UGX', 'VND', 'VUV', 'XAF', 'XOF', 'XPF'];
let c;
if ($('Stripe Payment').isExecuted) {
  const o = $('Stripe Payment').first().json.data?.object ?? {};
  const cd = o.customer_details ?? {};
  const md = o.metadata ?? {};
  const field = k => (o.custom_fields ?? []).find(f => f.key === k)?.text?.value;
  const currency = String(o.currency ?? '').toUpperCase();
  c = {
    source: 'Stripe',
    payment_id: String(o.payment_intent || o.id || ''),
    paid: o.payment_status === 'paid',
    company: field('company') || md.company || cd.name || cd.email || 'New client',
    contact_name: cd.name || '',
    email: String(cd.email || o.customer_email || '').trim().toLowerCase(),
    phone: cd.phone || '',
    package: md.package || s.default_package,
    amount: Number(o.amount_total || 0) / (ZERO_DECIMAL.includes(currency) ? 1 : 100),
    currency,
    start_date: DateTime.now().toISODate(),
  };
} else {
  const f = $('Manual Payment Form').first().json;
  c = {
    source: 'Manual',
    payment_id: 'manual:' + String(f.reference || '').trim().toLowerCase(),
    paid: true,
    company: String(f.company || '').trim(),
    contact_name: String(f.contact || '').trim(),
    email: String(f.email || '').trim().toLowerCase(),
    phone: String(f.phone || '').trim(),
    package: f.package || s.default_package,
    amount: Number(f.amount) || 0,
    currency: String(f.currency || 'IDR').trim().toUpperCase(),
    start_date: f.start_date || DateTime.now().toISODate(),
  };
}
return [{ json: {
  ...c,
  client_id: 'CL-' + DateTime.now().toFormat('yyMMdd') + '-' + $execution.id,
  first_name: String(c.contact_name).split(/\s+/)[0] || 'there',
  amount_text: c.amount.toLocaleString('id-ID') + ' ' + c.currency,
} }];

// One item per subfolder from the settings.
const s = $('Onboarding Settings').first().json;
const parent = $('Create Client Folder').first().json.id;
return String(s.subfolders).split(',').map(n => n.trim()).filter(Boolean).map(name => ({ json: { name, parent } }));

// Folder IDs for the next steps. Missing subfolders fall back to the client folder.
const s = $('Onboarding Settings').first().json;
const client = $('Create Client Folder').first().json.id;
const subs = $('Create Subfolder').all().map(i => i.json);
const byName = n => subs.find(f => f.name === n)?.id || client;
return [{ json: {
  client_folder_id: client,
  client_folder_url: 'https://drive.google.com/drive/folders/' + client,
  contract_folder_id: byName(s.contract_subfolder),
  shared_folder_id: byName(s.shared_subfolder),
  shared_folder_url: 'https://drive.google.com/drive/folders/' + byName(s.shared_subfolder),
} }];

