// The brief answers as plain text (for the Google Doc) and HTML (for the team email).
const f = $('Project Brief Form').first().json;
const q = [
  ['Company', f.company], ['What should this project achieve?', f.goals], ['Who are your customers?', f.audience],
  ['Websites or brands you like, and why', f.references], ['Content and brand assets they already have', f.assets],
  ['Deadline or launch date', f.deadline], ['Who approves the work?', f.approver], ['Anything else', f.notes],
].filter(([, a]) => a !== null && a !== undefined && String(a).trim() !== '');
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: {
  client_id: String(f.client_id || '').trim(),
  company: String(f.company || '').trim(),
  text: 'Project brief, received ' + DateTime.now().toFormat('d LLLL yyyy') + '\n\n' + q.map(([k, a]) => k + '\n' + String(a).trim()).join('\n\n') + '\n',
  html: q.map(([k, a]) => '<p><b>' + esc(k) + '</b><br>' + esc(String(a).trim()).replace(/\n/g, '<br>') + '</p>').join(''),
} }];

