// Clients still waiting for their brief: a reminder every reminder_after_days, at most max_reminders.
const s = $('Onboarding Settings').first().json;
const now = DateTime.now();
const out = [];
for (const r of $input.all().map(i => i.json)) {
  if (r.Status !== 'Waiting for brief' || !r.Email) continue;
  const created = DateTime.fromISO(String(r['Created At'] || ''));
  if (!created.isValid) continue;
  const sent = Number(r['Reminders Sent'] || 0);
  if (sent >= Number(s.max_reminders)) continue;
  const last = DateTime.fromISO(String(r['Last Reminder At'] || ''));
  if (now.diff(last.isValid ? last : created, 'days').days < Number(s.reminder_after_days)) continue;
  const final = sent + 1 >= Number(s.max_reminders);
  const first = String(r.Contact || '').trim().split(/\s+/)[0] || 'there';
  out.push({ json: {
    client_id: r['Client ID'], to: r.Email, cc: final ? s.team_email : '', count: sent + 1,
    subject: 'Reminder: your project brief for ' + s.agency_name,
    body: 'Hi ' + first + ',\n\nTo start work on your ' + (r.Package || 'project') + ', we need your project brief. It takes about 10 minutes:\n' +
      s.brief_form_url + '?client_id=' + encodeURIComponent(r['Client ID']) + '\n\nIf anything is unclear, just reply to this email.\n\nBest regards,\n' + s.sender_name + '\n' + s.agency_name,
  } });
}
return out;

